let array = $('Edit Fields3').first().json.turnos;
let data = $('Code6').first().json;
array.push(data);

return $input.all()

const datos = $input.all();

const fechaMinima = new Date("2026-04-06");

const datosValidos = datos.filter(item => 
  item?.json &&
  item.json.date &&
  item.json.hour &&
  item.json.hour.code &&
  (item.json.workshop_appointment_guid === null || item.json.workshop_appointment_guid === undefined) &&
  // item.json.user?.name === "AVANT Recepcion.Taller" &&
  new Date(item.json.date) >= fechaMinima  // ← línea agregada
);

const agrupadosPorFecha = {};

datosValidos.forEach(item => {
  const fecha = item.json.date;
  if (!agrupadosPorFecha[fecha]) {
    agrupadosPorFecha[fecha] = [];
  }
  agrupadosPorFecha[fecha].push(item);
});

const resultadoFinal = [];
const fechasDisponibles = Object.keys(agrupadosPorFecha);

fechasDisponibles.sort(() => Math.random() - 0.5);

for (const fecha of fechasDisponibles) {
  if (resultadoFinal.filter(t => t.json.date === fecha).length >= 2) continue;

  const turnosDelDia = agrupadosPorFecha[fecha];
  const turnosUsados = [];

  turnosDelDia.sort(() => Math.random() - 0.5);

  for (const turno of turnosDelDia) {
    const horaDuplicada = turnosUsados.some(t => t.json.hour.code === turno.json.hour.code);
    if (!horaDuplicada) {
      turnosUsados.push(turno);
    }
    if (turnosUsados.length === 2) break;
  }

  turnosUsados.forEach(t => resultadoFinal.push({
    json: {
      date: t.json.date,
      hour: t.json.hour.name
    }
  }));

  const diasDistintos = new Set(resultadoFinal.map(t => t.json.date)).size;
  if (diasDistintos >= 3 && resultadoFinal.length >= 6) break;
}

return resultadoFinal;

